using System;

unsafe
{
    int x = 42;
    int* ptr = &x;
    Console.WriteLine(*ptr);
}

using System;

unsafe
{
    int value = 100;
    int* ptr = &value;
    Console.WriteLine(*ptr);
}

int num = 5;
Modify(ref num);
Console.WriteLine(num);

static void Modify(ref int p) => p *= 2;

using System;

unsafe
{
    int* ptr = (int*)System.Runtime.InteropServices.Marshal.AllocHGlobal(sizeof(int));
    *ptr = 99;
    Console.WriteLine(*ptr);
    System.Runtime.InteropServices.Marshal.FreeHGlobal((IntPtr)ptr);
}

var p = new Person { Name = "Bob" };
Console.WriteLine(p.Name);

class Person { public string Name = ""; }

using System;

unsafe
{
    int* ptr = null;
    Console.WriteLine(ptr == null ? "nil" : ptr->ToString());
}

int x = 5, y = 10;
Swap(ref x, ref y);
Console.WriteLine($"{x} {y}");

static void Swap(ref int a, ref int b) { (a, b) = (b, a); }
